SELECT p.*, u.nickname, u.avatar_url FROM square_post p LEFT JOIN user u ON p.user_id = u.user_id WHERE p.is_deleted = 0 AND p.course_id = #{courseId} AND p.status = #{status}
AND (p.content LIKE CONCAT('%', #{keyword}, '%') OR p.tags LIKE CONCAT('%', #{keyword}, '%') OR p.course_name LIKE CONCAT('%', #{keyword}, '%') OR p.material_name LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%'))
AND p.tags LIKE CONCAT('%', #{tag}, '%')
ORDER BY p.create_time DESC, p.post_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM square_post p LEFT JOIN user u ON p.user_id = u.user_id WHERE p.is_deleted = 0 AND p.course_id = #{courseId} AND p.status = #{status}
AND (p.content LIKE CONCAT('%', #{keyword}, '%') OR p.tags LIKE CONCAT('%', #{keyword}, '%') OR p.course_name LIKE CONCAT('%', #{keyword}, '%') OR p.material_name LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%'))
AND p.tags LIKE CONCAT('%', #{tag}, '%')
